export const ASSETS = {"/":"<!doctype html><html lang=\"ar\" dir=\"rtl\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>مِضمار – لوحة المعلم</title><link rel=\"stylesheet\" href=\"/style.css\"></head><body><div id=\"app\"></div><script src=\"/admin.js\"></script></body></html>\n","/index.html":"<!doctype html><html lang=\"ar\" dir=\"rtl\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>مِضمار – لوحة المعلم</title><link rel=\"stylesheet\" href=\"/style.css\"></head><body><div id=\"app\"></div><script src=\"/admin.js\"></script></body></html>\n","/admin.js":"const $=(s,r=document)=>r.querySelector(s),app=$('#app');\nconst esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nasync function api(u,m='GET',b){const r=await fetch(u,{method:m,headers:b?{'Content-Type':'application/json'}:{},body:b?JSON.stringify(b):undefined});\n const j=await r.json().catch(()=>({}));if(!r.ok)throw Error(j.error||'حدث خطأ');return j}\nfunction toast(t){const e=document.createElement('div');e.className='toast';e.textContent=t;document.body.append(e);setTimeout(()=>e.remove(),2500)}\nfunction confirmBox(msg){return new Promise(res=>{const d=document.createElement('dialog');d.innerHTML=`<p>${esc(msg)}</p><div class=row><button class=\"btn d\" value=y>نعم، تأكيد</button><button class=btn value=n>إلغاء</button></div>`;\n document.body.append(d);d.showModal();d.onclick=e=>{if(e.target.value){d.close();d.remove();res(e.target.value==='y')}}})}\nlet me=null;\n\nconst THEME_KEY='midmar-theme';\nconst storedTheme=()=>localStorage.getItem(THEME_KEY);\nlet currentTheme=storedTheme()|| (matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light');\nfunction applyTheme(theme,save=true){\n currentTheme=theme==='dark'?'dark':'light';\n document.documentElement.dataset.theme=currentTheme;\n if(save)localStorage.setItem(THEME_KEY,currentTheme);\n const btn=$('#themeToggle');\n if(btn){btn.innerHTML=currentTheme==='dark'?'<span aria-hidden=\"true\">☀</span><span>الوضع الساطع</span>':'<span aria-hidden=\"true\">☾</span><span>الوضع المظلم</span>';btn.setAttribute('aria-label',currentTheme==='dark'?'التبديل إلى الوضع الساطع':'التبديل إلى الوضع المظلم');btn.title=btn.getAttribute('aria-label')}\n document.querySelectorAll('[data-theme-choice]').forEach(x=>x.classList.toggle('p',x.dataset.themeChoice===currentTheme));\n const status=$('#themeModeStatus');if(status)status.textContent=currentTheme==='dark'?'الوضع المظلم مفعّل':'الوضع الساطع مفعّل';\n}\nfunction toggleTheme(){applyTheme(currentTheme==='dark'?'light':'dark')}\napplyTheme(currentTheme,false);\n\nasync function loginScreen(){\n const error=new URLSearchParams(location.search).get('auth_error');\n const message=error==='not_configured'?'تسجيل Google غير مهيأ في إعدادات الخادم.':error?'تعذر تسجيل الدخول عبر Google. حاول مرة أخرى.':'';\n app.innerHTML=`<main class=\"center\"><section class=\"card narrow login-card\"><h1>مِضمار</h1><p>سجّل الدخول بحساب Google لعرض مسابقاتك وأعمالك الخاصة.</p>${message?`<p class=\"err\">${esc(message)}</p>`:''}<a class=\"btn p google-login\" href=\"/auth/google\"><span aria-hidden=\"true\">G</span> تسجيل الدخول باستخدام Google</a><small>كل حساب له مساحة خاصة لا يطلع عليها الآخرون.</small></section></main>`;\n}\nlet onboardingState=null;\nconst tourSteps=[\n {title:'الرئيسية',text:'هنا تتابع عدد مسابقاتك والمجموعات المشاركة ومتوسط الدرجات وأعلى نتيجة.'},\n {title:'المسابقات',text:'من صفحة المسابقات تدير اختباراتك، وتفتح النتائج، وتعدّل المسابقة أو تنسخها أو تؤرشفها.'},\n {title:'إنشاء مسابقة',text:'أنشئ مسابقة جديدة، أضف الأسئلة والخيارات وحدد الإجابة الصحيحة والوقت وطريقة المشاركة.'},\n {title:'لوحة العرض ورمز الدخول',text:'ابدأ المسابقة وافتح لوحة العرض. شارك رمز الدخول أو رمز QR مع الطلاب للانضمام.'},\n {title:'النتائج والتقارير',text:'تابع ترتيب المجموعات والدرجات والإحصاءات، ويمكنك تصدير النتائج عند توفرها.'},\n {title:'الإعدادات',text:'راجع الحساب، ويمكنك الرجوع إلى هذا الشرح لاحقًا من صفحة الإعدادات.'}\n];\nasync function finishOnboarding(){await api('/api/onboarding/complete','POST');onboardingState={version:2,showTutorial:false,showUpdateNotice:false}}\nfunction showTour(){\n let i=0;const d=document.createElement('dialog');d.className='brand-dialog';\n const draw=()=>{const x=tourSteps[i];d.innerHTML=`<div class=\"brand-card\" style=\"display:block\"><small>دليل مِضمار · ${i+1} من ${tourSteps.length}</small><h2>${esc(x.title)}</h2><p>${esc(x.text)}</p><div class=\"row\"><button class=\"btn\" id=\"tourSkip\">تخطي الشرح</button><span class=\"sp\"></span><button class=\"btn p\" id=\"tourNext\">${i===tourSteps.length-1?'إنهاء':'التالي'}</button></div></div>`;\n $('#tourSkip',d).onclick=async()=>{await finishOnboarding();d.close();d.remove()};\n $('#tourNext',d).onclick=async()=>{if(i<tourSteps.length-1){i++;draw()}else{await finishOnboarding();d.close();d.remove();toast('اكتمل الشرح')}}};\n document.body.append(d);draw();d.showModal();\n}\nasync function onboarding(){\n onboardingState=await api('/api/onboarding');\n if(onboardingState.showTutorial){showTour();return}\n if(onboardingState.showUpdateNotice){\n  const d=document.createElement('dialog');d.className='brand-dialog';\n  d.innerHTML='<div class=\"brand-card\" style=\"display:block\"><small>مِضمار 2.0</small><h2>تم تحديث مِضمار</h2><p>أضفنا دليلًا تفاعليًا يشرح أقسام الموقع وطريقة إنشاء المسابقات ومتابعة النتائج. يمكنك بدء الشرح الآن أو تشغيله لاحقًا من الإعدادات.</p><div class=\"row\"><button class=\"btn\" id=\"updateLater\">لاحقًا</button><span class=\"sp\"></span><button class=\"btn p\" id=\"updateStart\">ابدأ الشرح</button></div></div>';\n  document.body.append(d);d.showModal();\n  $('#updateLater',d).onclick=async()=>{await finishOnboarding();d.close();d.remove()};\n  $('#updateStart',d).onclick=()=>{d.close();d.remove();showTour()};\n }\n}\nasync function render(){\n me=await fetch('/api/me').then(r=>r.json()).catch(()=>({authenticated:false}));\n if(!me.authenticated){await loginScreen();return}\n const h=location.hash.slice(1)||'/';const m=h.match(/^\\/quiz\\/(new|\\d+)\\/?(edit|results)?$/);\n app.innerHTML=`<nav class=nav><div class=wrap><div class=nav-brand><span class=nav-emblem>م</span><div><strong>مِضمار</strong><small>منصة المسابقات التفاعلية</small></div></div><a href=\"#/\" data-p=\"/\">الرئيسية</a><a href=\"#/quizzes\" data-p=\"/quizzes\">المسابقات</a><a href=\"#/settings\" data-p=\"/settings\">الإعدادات</a><a class=nav-create href=\"#/quiz/new\" data-p=\"/quiz/new\">+ إنشاء مسابقة</a><div class=nav-account><span class=nav-avatar>م</span><small>${esc(me.email||\"حساب المعلم\")}</small></div><span class=sp></span><button class=\"btn theme-toggle\" id=\"themeToggle\" type=\"button\"></button><button class=\"btn nav-logout\" id=\"logoutBtn\" type=\"button\">تسجيل الخروج</button><button class=\"brand-mark\" id=\"brandOpen\" type=\"button\" aria-label=\"عرض بطاقة التطوير\" aria-haspopup=\"dialog\" aria-controls=\"brandDialog\"><span aria-hidden=\"true\">©</span></button><dialog class=\"brand-dialog\" id=\"brandDialog\" aria-labelledby=\"brandTitle\"><div class=\"brand-card\"><img src=\"/entrit-logo.svg\" alt=\"شعار أنتريت\"><div class=\"brand-copy\"><strong id=\"brandTitle\">تطوير أنتريت</strong><span>تم تطوير مِضمار بواسطة أنتريت</span><small id=\"brandVersion\">إصدار الموقع 1.0.0</small></div></div><button class=\"btn brand-close\" id=\"brandClose\" type=\"button\">إغلاق</button></dialog></div></nav><main class=wrap id=main></main>`;\n applyTheme(currentTheme,false);\n $('#themeToggle').onclick=toggleTheme;\n fetch('/api/version').then(r=>r.json()).then(v=>{const el=$('#brandVersion');if(el)el.textContent='إصدار الموقع '+v.version}).catch(()=>{});\n $('#logoutBtn').onclick=async()=>{await api('/api/logout','POST');me=null;location.hash='/';render()};\n document.querySelectorAll('.nav a[data-p]').forEach(a=>a.classList.toggle('on',a.dataset.p===h));\n const brandDialog=$('#brandDialog');$('#brandOpen').onclick=()=>brandDialog.showModal();$('#brandClose').onclick=()=>brandDialog.close();brandDialog.onclick=e=>{if(e.target===brandDialog)brandDialog.close()};\n const M=$('#main');try{await onboarding();if(h==='/')await home(M);else if(h==='/quizzes')await list(M);else if(h==='/settings')settings(M);\n  else if(m&&m[1]==='new')editor(M,null);else if(m&&m[2]==='results')await results(M,m[1]);else if(m)await editor(M,m[1]);else M.textContent='الصفحة غير موجودة'}catch(e){if(e.message!=='401')M.innerHTML='<p class=err>'+esc(e.message)+'</p>'}}\naddEventListener('hashchange',render);\nconst dur=s=>s>=60?`${Math.floor(s/60)}د ${s%60}ث`:s+'ث';\nfunction chart(d){const W=Math.max(320,d.length*90),mx=Math.max(1,...d.map(x=>x.max));return `<div style=\"overflow-x:auto\"><svg viewBox=\"0 0 ${W} 190\" width=\"${W}\" role=img aria-label=\"متوسط الدرجات لكل مسابقة\">${d.map((x,i)=>{const h=Math.round(120*x.avg/mx),X=i*90+20;\n return `<rect x=${X} y=${140-h} width=50 height=${h} rx=6 fill=\"var(--g)\"/><text x=${X+25} y=${134-h} text-anchor=middle fill=\"var(--ink)\" font-size=13>${x.avg}/${x.max}</text><text x=${X+25} y=165 text-anchor=middle fill=\"var(--mut)\" font-size=12>${esc(x.title.slice(0,10))}</text>`}).join('')}</svg></div>`}\nasync function home(M){const d=await api('/api/dashboard');M.innerHTML=`<header class=page-head><div><span class=eyebrow>لوحة المعلم</span><h1>مرحبًا بك في مِضمار</h1><p>أنشئ مسابقاتك، وأدر المشاركين، وتابع النتائج من مكان واحد.</p></div><a class=\"btn p page-head-action\" href=\"#/quiz/new\">+ إنشاء مسابقة جديدة</a></header><div class=grid>\n <div class=\"card stat\"><b>${d.quizzes}</b><span>إجمالي المسابقات (${d.active} نشطة)</span></div><div class=\"card stat\"><b>${d.groups}</b><span>إجمالي المجموعات المشاركة</span></div>\n <div class=\"card stat\"><b>${d.avg}</b><span>متوسط الدرجات</span></div><div class=\"card stat\"><b>${d.best?esc(d.best.name):'—'}</b><span>${d.best?`أعلى نتيجة: ${d.best.score}/${d.best.total} في «${esc(d.best.quiz)}»`:'لا توجد نتائج بعد'}</span></div></div>\n <div class=card style=\"margin-top:1em\"><h2>متوسط الدرجات حسب المسابقة</h2>${d.chart.length?chart(d.chart):'<p>أنشئي مسابقة لتظهر هنا النتائج.</p>'}</div>\n <div class=card style=\"margin-top:1em\"><h2>آخر المسابقات</h2>${d.recent.map(r=>`<p><a href=\"#/quiz/${r.id}/results\">${esc(r.title)}</a> ${r.archived?'<span class=tag>مؤرشفة</span>':''}</p>`).join('')||'<p>لا توجد مسابقات بعد.</p>'}</div>`}\nlet tab='active';\nasync function list(M){\n const all=await api('/api/quizzes');\n const L=all.filter(z=>tab==='active'?!z.archived:z.archived);\n let search='';\n M.innerHTML=`<div class=library-head><div><span class=eyebrow>إدارة المحتوى</span><h1>مكتبة المسابقات</h1><p>كل اختباراتك ومسابقاتك في مكان واحد.</p></div><a class=\"btn p\" href=\"#/quiz/new\">+ إنشاء مسابقة</a></div>\n <section class=library-toolbar><div class=library-tabs><button class=\"btn ${tab==='active'?'p':''}\" data-t=active>النشطة <span>${all.filter(z=>!z.archived).length}</span></button><button class=\"btn ${tab==='arch'?'p':''}\" data-t=arch>الأرشيف <span>${all.filter(z=>z.archived).length}</span></button></div><div class=library-search><span aria-hidden=true>⌕</span><input id=quizSearch type=search placeholder=\"ابحث باسم المسابقة أو رمزها...\" autocomplete=off></div></section>\n <div class=library-summary><strong id=libraryCount>${L.length}</strong><span>مسابقة في هذا القسم</span></div>\n <div id=quizGrid class=quiz-grid></div>`;\n const grid=$('#quizGrid',M),count=$('#libraryCount',M);\n const draw=()=>{\n  const q=search.trim().toLocaleLowerCase('ar');\n  const rows=L.filter(z=>String(z.title||'').toLocaleLowerCase('ar').includes(q)||String(z.code||'').includes(q));\n  count.textContent=rows.length;\n  grid.innerHTML=rows.map(z=>`<article class=card quiz-card><div class=quiz-card-top><div class=quiz-card-icon>${z.archived?'▣':'✦'}</div><div class=quiz-card-title><h3>${esc(z.title)}</h3><span class=quiz-status ${z.archived?'data-archived':''}>${z.archived?'مؤرشفة':'نشطة'}</span></div><div class=quiz-code><small>رمز الدخول</small><strong>${z.code}</strong></div></div><div class=quiz-facts><span><b>${z.nq}</b> سؤال</span><i></i><span><b>${z.ng}</b> مشارك</span></div><div class=quiz-actions><a class=\"btn p\" target=_blank rel=noopener href=\"/board/${z.code}\">لوحة المسابقة</a><a class=\"btn\" href=\"#/quiz/${z.id}/results\">النتائج</a><a class=\"btn\" href=\"#/quiz/${z.id}/edit\">تعديل</a><button class=\"btn\" data-a=copy data-id=${z.id}>نسخ</button><button class=\"btn\" data-a=arch data-id=${z.id}>${z.archived?'استعادة':'أرشفة'}</button><button class=\"btn d\" data-a=del data-id=${z.id}>حذف</button></div></article>`).join('')||`<div class=library-empty><div>⌕</div><h3>${q?'لا توجد نتائج مطابقة':'لا توجد مسابقات هنا'}</h3><p>${q?'جرّب البحث باسم مختلف أو رمز الدخول.':'أنشئ أول مسابقة لتظهر هنا.'}</p>${q?'':'<a class=\"btn p\" href=\"#/quiz/new\">إنشاء مسابقة</a>'}</div>`;\n };\n draw();\n $('#quizSearch',M).oninput=e=>{search=e.target.value;draw()};\n M.onclick=async e=>{\n  const b=e.target.closest('button');if(!b)return;\n  if(b.dataset.t){tab=b.dataset.t;return list(M)}\n  const id=b.dataset.id,z=all.find(x=>x.id==id);\n  try{\n   if(b.dataset.a==='copy'){await api(`/api/quizzes/${id}/copy`,'POST');toast('تم نسخ المسابقة');return list(M)}\n   if(b.dataset.a==='arch'){await api(`/api/quizzes/${id}/archive`,'POST');toast(z.archived?'تمت استعادة المسابقة':'تمت أرشفة المسابقة');return list(M)}\n   if(b.dataset.a==='del'&&await confirmBox(`حذف «${z.title}» ونتائجها نهائيًا؟`)){await api('/api/quizzes/'+id,'DELETE');toast('تم الحذف');return list(M)}\n  }catch(err){toast(err.message)}\n };\n}\nfunction share(z){const url=`${location.origin}/j/${z.code}`,d=document.createElement('dialog');d.innerHTML=`<h3>${esc(z.title)}</h3><img alt=\"QR\" src=\"/api/qr?text=${encodeURIComponent(url)}\" width=220 height=220 style=\"display:block;margin:auto;background:#fff\"><p>رمز الدخول: <b style=\"font-size:1.4em\">${z.code}</b></p><input readonly value=\"${url}\" onfocus=this.select()><div class=row style=\"margin-top:.7em\"><button class=\"btn p\" id=cp>نسخ الرابط</button><button class=btn id=cl>إغلاق</button></div>`;\n document.body.append(d);d.showModal();$('#cp',d).onclick=()=>navigator.clipboard.writeText(url).then(()=>toast('تم النسخ'));$('#cl',d).onclick=()=>{d.close();d.remove()}}\nasync function settings(M){\n const d=await api('/api/me');\n M.innerHTML=`<div class=section-heading><span class=eyebrow>التفضيلات والحساب</span><h1>الإعدادات</h1><p>تحكم في مظهر مِضمار وتفاصيل حسابك.</p></div>\n <div class=settings-grid>\n  <section class=card settings-card><div class=settings-icon>◐</div><div><h2>مظهر الموقع</h2><p>اختر الألوان المناسبة لك. يُحفظ اختيارك على هذا الجهاز ويُطبّق على صفحات المعلم والطالب ولوحة العرض.</p></div>\n   <div class=theme-choices><button class=\"btn\" data-theme-choice=light type=button>☀ الوضع الساطع</button><button class=\"btn\" data-theme-choice=dark type=button>☾ الوضع المظلم</button></div><small id=themeModeStatus class=settings-hint></small>\n  </section>\n  <section class=card settings-card><div class=settings-icon>◎</div><div><h2>حسابك</h2><p><b>البريد الإلكتروني:</b> ${esc(d.email||'—')}</p><p><b>طريقة الدخول:</b> Google</p><small class=settings-hint>تُحفظ مسابقاتك ضمن مساحة حسابك الخاصة.</small></div></section>\n  <section class=card settings-card><div class=settings-icon>?</div><div><h2>المساعدة</h2><p>يمكنك إعادة مشاهدة شرح أقسام الموقع وطريقة إنشاء المسابقات ومتابعة النتائج.</p><button class=\"btn p\" id=replayTour>إعادة شرح الموقع</button></div></section>\n </div>`;\n applyTheme(currentTheme,false);\n document.querySelectorAll('[data-theme-choice]').forEach(x=>x.onclick=()=>applyTheme(x.dataset.themeChoice));\n $('#replayTour').onclick=showTour;\n}\nconst toMs=v=>v?new Date(v).getTime():null,fromMs=v=>v?new Date(v-new Date().getTimezoneOffset()*6e4).toISOString().slice(0,16):'';\nconst readImg=f=>new Promise((res,rej)=>{if(!f)return res('');if(f.size>1.5e6)return rej(Error('الصورة كبيرة (الحد 1.5 ميغابايت)'));const r=new FileReader();r.onload=()=>res(r.result);r.readAsDataURL(f)});\nasync function editor(M,id){\n const z=id?await api('/api/quizzes/'+id):{title:'',description:'',image:'',time_limit:0,shuffle_q:0,shuffle_a:0,show_correct:1,allow_retry:0,start_at:null,end_at:null,participation_mode:'groups',entry_mode:'both',progression_mode:'sequential',roster:'',questions:[],ng:0};\n const locked=id&&(await api('/api/quizzes')).find(x=>x.id==id).ng>0;let Q=z.questions.map(x=>({...x})),step=0;\n const ck=(k,t)=>`<label style=\"display:flex;gap:.5em;align-items:center;font-weight:400\"><input type=checkbox id=${k} style=\"width:auto\" ${z[k]?'checked':''}>${t}</label>`;\n M.innerHTML=`<div class=row><h1 class=sp>${id?'تعديل المسابقة':'إنشاء مسابقة جديدة'}</h1><a class=btn href=\"#/quizzes\">رجوع</a></div><div class=card>\n <div class=row id=steps><span class=tag>1 · بيانات المسابقة</span><span class=tag>2 · المشاركة</span><span class=tag>3 · الأسئلة</span></div>\n <section data-step=0><h2>بيانات المسابقة</h2><label>اسم المسابقة</label><input id=title value=\"${esc(z.title)}\"><label>الوصف / التعليمات</label><textarea id=desc rows=3>${esc(z.description)}</textarea>\n <label>صورة المسابقة</label><input type=file id=img accept=\"image/*\"><div id=coverPreview>${z.image?`<img src=\"${z.image}\" style=\"max-height:100px\">`:''}</div>\n <div class=grid><div><label>المدة بالدقائق (0 بلا حد)</label><input type=number min=0 id=tl value=${z.time_limit}></div><div><label>موعد البدء</label><input type=datetime-local id=sa value=\"${fromMs(z.start_at)}\"></div><div><label>موعد الإغلاق</label><input type=datetime-local id=ea value=\"${fromMs(z.end_at)}\"></div></div>\n <hr><h3>إعدادات عرض الأسئلة</h3>${ck('shuffle_q','ترتيب الأسئلة عشوائي')}${ck('shuffle_a','ترتيب الإجابات عشوائي')}${ck('show_correct','إظهار الإجابة الصحيحة')}${ck('allow_retry','السماح بإعادة المحاولة')}</section>\n <section data-step=1 hidden><h2>طريقة المشاركة</h2><label>نوع المشاركة</label><select id=participation_mode><option value=groups ${z.participation_mode!=='students'?'selected':''}>مجموعات – جهاز لكل مجموعة</option><option value=students ${z.participation_mode==='students'?'selected':''}>طلاب – كل طالب بجهازه</option></select>\n <label>طريقة التسجيل</label><select id=entry_mode><option value=both ${!z.entry_mode||z.entry_mode==='both'?'selected':''}>قائمة المعلم أو تسجيل ذاتي</option><option value=qr ${z.entry_mode==='qr'?'selected':''}>QR أو الرابط</option><option value=roster ${z.entry_mode==='roster'?'selected':''}>قائمة المعلم فقط</option></select>\n <label>أسماء الطلاب (اسم في كل سطر)</label><textarea id=roster rows=5>${esc(z.roster||'')}</textarea>\n <label>طريقة الانتقال بين الأسئلة</label><select id=progression_mode><option value=sequential ${!z.progression_mode||z.progression_mode==='sequential'?'selected':''}>تسلسلي</option><option value=free ${z.progression_mode==='free'?'selected':''}>حر</option><option value=teacher ${z.progression_mode==='teacher'?'selected':''}>تحكم المعلم</option></select></section>\n <section data-step=2 hidden><h2>الأسئلة</h2><div class=card><h3>إنشاء الأسئلة من صورة</h3><input type=file id=sheet accept=\"image/*\"><button class=btn id=readSheet type=button>قراءة الورقة بالذكاء الاصطناعي</button><small id=aiStatus>ترفع الصورة ثم راجع الأسئلة المستخرجة قبل اعتمادها.</small></div>\n <div id=qs></div>${locked?'':'<div class=row><button class=btn id=addmc>+ اختيار متعدد</button><button class=btn id=addtf>+ صح أو خطأ</button><button class=btn id=addorder>+ رتّب العناصر</button></div>'}</section>\n <p class=err id=e></p><div class=row style=\"justify-content:space-between;margin-top:1em\"><button class=btn id=prev hidden>السابق</button><span class=sp></span><button class=\"btn p\" id=next>التالي</button><button class=\"btn p\" id=save hidden>إنشاء المسابقة</button></div></div>`;\n const show=()=>{M.querySelectorAll('[data-step]').forEach(x=>x.hidden=+x.dataset.step!==step);M.querySelectorAll('#steps .tag').forEach((x,i)=>x.style.opacity=i===step?'1':'.45');$('#prev').hidden=step===0;$('#next').hidden=step===2;$('#save').hidden=step!==2};show();\n const draw=()=>{$('#qs').innerHTML=Q.map((q,i)=>`<div class=q data-i=${i}><div class=row><b>سؤال ${i+1} · ${q.type==='tf'?'صح أو خطأ':q.type==='order'?'رتّب العناصر':'اختيار متعدد'}</b><span class=sp></span><label>الدرجة <input type=number min=1 data-f=points value=${q.points} style=\"width:4em\"></label>${locked?'':'<button class=\"btn s d\" data-del>حذف</button>'}</div><label>نص السؤال</label><textarea data-f=text>${esc(q.text)}</textarea><label>${q.type==='order'?'العناصر بالترتيب الصحيح':'الخيارات'}</label>${(q.type==='tf'?['صح','خطأ']:q.options).map((o,j)=>`<div class=opt>${q.type==='order'?`<b>${j+1}.</b>`:'<input type=radio name=c'+i+' data-c='+j+(q.correct===j?' checked':'')+'>'}<input data-o=${j} value=\"${esc(o)}\" placeholder=\"عنصر ${j+1}\"><button class=\"btn s\" data-rm=${j} ${q.options.length<=2?'disabled':''}>×</button></div>`).join('')}${q.type!=='tf'&&q.options.length<6&&!locked?'<button class=btn data-addo>+ خيار</button>':''}</div>`).join('')||'<p>أضف سؤالًا من الأزرار.</p>';};\n draw();const box=$('#qs');\n box.oninput=e=>{const el=e.target.closest('.q');if(!el)return;const q=Q[+el.dataset.i],t=e.target;if(t.dataset.f)q[t.dataset.f]=t.dataset.f==='points'?+t.value:t.value;if(t.dataset.o!==undefined)q.options[+t.dataset.o]=t.value};\n box.onchange=async e=>{const el=e.target.closest('.q');if(el&&e.target.dataset.c!==undefined)Q[+el.dataset.i].correct=+e.target.dataset.c};\n box.onclick=e=>{const b=e.target.closest('button'),el=b?.closest('.q');if(!el)return;const q=Q[+el.dataset.i];if('del'in b.dataset)Q.splice(+el.dataset.i,1);else if('addo'in b.dataset)q.options.push('');else if(b.dataset.rm!==undefined)q.options.splice(+b.dataset.rm,1);else return;draw()};\n if(!locked){$('#addmc').onclick=()=>{Q.push({type:'mc',text:'',points:1,options:['','','',''],correct:null});draw()};$('#addtf').onclick=()=>{Q.push({type:'tf',text:'',points:1,options:['صح','خطأ'],correct:null});draw()};$('#addorder').onclick=()=>{Q.push({type:'order',text:'',points:1,options:['','',''],correct:null});draw()}}\n $('#img').onchange=async e=>{try{z.image=await readImg(e.target.files[0]);$('#coverPreview').innerHTML=z.image?`<img src=\"${z.image}\" style=\"max-height:100px\">`:''}catch(x){toast(x.message)}};\n $('#prev').onclick=()=>{step=Math.max(0,step-1);show()};$('#next').onclick=()=>{if(step===0&&!$('#title').value.trim())return toast('اكتب اسم المسابقة أولًا');step=Math.min(2,step+1);show()};\n $('#readSheet').onclick=async()=>{const f=$('#sheet').files[0];if(!f)return toast('اختر صورة الورقة');try{const image=await readImg(f);$('#aiStatus').textContent='جارٍ تحليل الصورة...';const r=await api('/api/ai/parse-sheet','POST',{image});Q.push(...r.questions);draw();$('#aiStatus').textContent='استخرجنا '+r.questions.length+' سؤال. راجع الإجابات قبل الحفظ.'}catch(e){$('#aiStatus').textContent=e.message;toast(e.message)}};\n $('#save').onclick=async()=>{const body={title:$('#title').value,description:$('#desc').value,image:z.image,time_limit:$('#tl').value,start_at:toMs($('#sa').value),end_at:toMs($('#ea').value),shuffle_q:$('#shuffle_q').checked,shuffle_a:$('#shuffle_a').checked,show_correct:$('#show_correct').checked,allow_retry:$('#allow_retry').checked,participation_mode:$('#participation_mode').value,entry_mode:$('#entry_mode').value,progression_mode:$('#progression_mode').value,roster:$('#roster').value,questions:Q};try{if(id)await api('/api/quizzes/'+id,'PUT',body);else{if(!Q.length)throw Error('أضف سؤالًا واحدًا على الأقل');await api('/api/quizzes','POST',body)}toast('تم الحفظ');location.hash='#/quizzes'}catch(e){$('#e').textContent=e.message}};\n}\nasync function results(M,id){const r=await api(`/api/quizzes/${id}/results`),z=r.quiz;\n M.innerHTML=`<div class=row><h1 class=sp>نتائج: ${esc(z.title)}</h1><a class=\"btn p\" target=_blank href=\"/board/${z.code}\">ابدأ المسابقة</a>${r.progression_mode==='teacher'?'<button class=\"btn p\" id=\"unlockNext\">فتح السؤال التالي للمشاركين</button>':''}<a class=\"btn p\" href=\"/api/quizzes/${id}/export.csv\">تصدير CSV</a></div>\n <div class=row><button class=btn id=hide>إخفاء النتائج عن الشاشة</button><button class=btn id=show>إظهار النتائج</button></div>\n <div class=grid style=\"margin:1em 0\"><div class=\"card stat\"><b>${r.rows.length}</b><span>مجموعة</span></div><div class=\"card stat\"><b>${r.avg}/${r.totalPoints}</b><span>متوسط الدرجات</span></div>\n <div class=\"card stat\"><b>${r.hardest?esc(r.hardest.text.slice(0,30)):'—'}</b><span>أصعب سؤال${r.hardest?` (${r.hardest.pct}% صحيح)`:''}</span></div><div class=\"card stat\"><b>${r.easiest?esc(r.easiest.text.slice(0,30)):'—'}</b><span>أسهل سؤال${r.easiest?` (${r.easiest.pct}% صحيح)`:''}</span></div></div>\n <div class=card style=\"overflow-x:auto\"><h2>ترتيب المجموعات</h2><table><tr><th>المركز<th>المجموعة<th>الدرجة<th>صحيحة<th>خاطئة<th>النسبة<th>الوقت<th>الحالة<th></tr>${r.rows.map(x=>`<tr><td>${x.rank}${x.tie?' <span class=tag>تعادل</span>':''}<td>${esc(x.name)}<td>${x.score}/${r.totalPoints}<td>${x.correct}<td>${x.answered-x.correct}<td>${x.answered?Math.round(100*x.correct/x.answered):0}%<td>${dur(x.duration)}<td>${x.done?'أنهت':'تلعب'}<td><button class=\"btn s d\" data-g=${x.id}>حذف</button></tr>`).join('')||'<tr><td colspan=9>لا توجد مجموعات بعد</tr>'}</table></div>\n <div class=card style=\"margin-top:1em;overflow-x:auto\"><h2>تحليل الأسئلة</h2><table><tr><th>السؤال<th>صحيحة<th>خاطئة<th>نسبة الصحة</tr>${r.questions.map(x=>`<tr><td>${esc(x.text.slice(0,60))}${r.mostMissed.some(m=>m.id===x.id)?' <span class=tag>أخطأت فيه معظم المجموعات</span>':''}<td>${x.correct}<td>${x.wrong}<td>${x.pct===null?'—':x.pct+'%'}</tr>`).join('')}</table></div>`;\n const st=s=>async()=>{await api(`/api/quizzes/${id}/board`,'POST',{state:s});toast(s==='hidden'?'أُخفيت النتائج':'أُظهرت النتائج')};if(r.progression_mode==='teacher')$('#unlockNext').onclick=async()=>{try{await api(`/api/quizzes/${id}/unlock`,'POST',{});toast('تم فتح السؤال التالي')}catch(e){toast(e.message)}};$('#hide').onclick=st('hidden');$('#show').onclick=st('shown');\n M.onclick=async e=>{const b=e.target.closest('[data-g]');if(b&&await confirmBox('حذف هذه المجموعة ونتائجها؟')){await api('/api/groups/'+b.dataset.g,'DELETE');results(M,id)}}}\nrender();\n","/style.css":"@import url('https://fonts.googleapis.com/css2?family=IBM+Plex+Sans+Arabic:wght@400;500;700&display=swap');\n:root{--ink:#12263A;--mut:#5B6B7B;--bg:#F2F5F8;--card:#fff;--line:#DDE4EB;--g:#0E7C5A;--g2:#0A5C43;--gold:#F2B705;--red:#C23A3A;--ok:#1E8E5A;--r:12px}\n@media(prefers-color-scheme:dark){:root{--ink:#E8EEF4;--mut:#9AABBB;--bg:#0F1A24;--card:#16242F;--line:#27394A}}\n*{box-sizing:border-box}html{-webkit-text-size-adjust:100%}\nbody{margin:0;font:16px/1.7 'IBM Plex Sans Arabic',Tahoma,sans-serif;color:var(--ink);background:var(--bg)}\nh1,h2,h3{line-height:1.3;margin:.2em 0 .5em}a{color:var(--g)}\nbutton,input,select,textarea{font:inherit;color:inherit}\n.btn{display:inline-flex;align-items:center;gap:.4em;border:1px solid var(--line);background:var(--card);padding:.5em 1em;border-radius:10px;cursor:pointer;text-decoration:none;min-height:44px}\n.btn:hover{border-color:var(--g)}.btn.p{background:var(--g);border-color:var(--g);color:#fff}.btn.p:hover{background:var(--g2)}.btn.d{color:var(--red)}.btn.s{min-height:36px;padding:.2em .7em;font-size:.9em}\n:focus-visible{outline:3px solid var(--gold);outline-offset:2px}\ninput,select,textarea{width:100%;padding:.55em .8em;border:1px solid var(--line);border-radius:10px;background:var(--card)}\nlabel{display:block;font-weight:500;margin:.8em 0 .2em}\n.card{background:var(--card);border:1px solid var(--line);border-radius:var(--r);padding:1.1em 1.3em}\n.wrap{max-width:1100px;margin:0 auto;padding:1em}\n.nav{background:var(--g2);color:#fff;position:sticky;top:0;z-index:5}.nav .wrap{display:flex;gap:.3em;align-items:center;flex-wrap:wrap;padding:.5em 1em}\n.nav a{color:#fff;text-decoration:none;padding:.4em .9em;border-radius:8px}.nav a.on,.nav a:hover{background:rgba(255,255,255,.18)}.nav b{font-size:1.3em;margin-inline-end:1em}\n.grid{display:grid;gap:1em;grid-template-columns:repeat(auto-fit,minmax(200px,1fr))}\n.stat b{display:block;font-size:2em;line-height:1.2}.stat span{color:var(--mut)}\ntable{width:100%;border-collapse:collapse}th,td{text-align:right;padding:.55em .7em;border-bottom:1px solid var(--line)}th{color:var(--mut);font-weight:500}\n.row{display:flex;gap:.6em;align-items:center;flex-wrap:wrap}.sp{flex:1}\n.tag{display:inline-block;padding:0 .7em;border-radius:99px;background:var(--line);font-size:.85em}\n.q{border:1px solid var(--line);border-radius:var(--r);padding:1em;margin:.8em 0;background:var(--card)}.q.over{border-color:var(--g);border-style:dashed}\n.handle{cursor:grab;color:var(--mut);font-size:1.3em;user-select:none}\n.opt{display:flex;gap:.5em;align-items:center;margin:.3em 0}.opt input[type=radio]{width:auto}\n.err{color:var(--red);min-height:1.5em}\n.toast{position:fixed;bottom:1em;left:50%;transform:translateX(-50%);background:var(--ink);color:var(--bg);padding:.6em 1.2em;border-radius:10px;z-index:99}\ndialog{border:1px solid var(--line);border-radius:var(--r);background:var(--card);color:var(--ink);max-width:min(92vw,420px)}\n.center{min-height:100vh;display:grid;place-items:center;padding:1em}.narrow{width:min(100%,440px)}\n.bar{height:10px;border-radius:9px;background:var(--line);overflow:hidden}.bar i{display:block;height:100%;background:var(--g);transition:width .4s}\n@media(prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important}}\n\n/* Entrit ownership card */\n.brand-mark{width:40px;height:40px;flex:0 0 40px;margin-inline-start:auto;border:1px solid rgba(255,255,255,.65);border-radius:11px;display:grid;place-items:center;background:rgba(255,255,255,.13);color:#fff;font:700 22px/1 Arial,sans-serif;cursor:pointer;transition:background .18s,transform .18s}\n.brand-mark:hover{background:rgba(255,255,255,.24);transform:translateY(-1px)}\n.brand-dialog{width:min(92vw,390px);max-width:390px;padding:0;border:1px solid var(--line);border-radius:18px;background:var(--card);color:var(--ink);box-shadow:0 18px 55px #0003}\n.brand-dialog::backdrop{background:rgba(5,18,28,.58);backdrop-filter:blur(3px)}\n.brand-card{display:flex;align-items:center;gap:16px;padding:24px 22px}\n.brand-card img{width:84px;height:84px;flex:0 0 84px;object-fit:contain;border-radius:14px;background:var(--bg);padding:7px}\n.brand-copy{display:flex;flex-direction:column;gap:5px;min-width:0}\n.brand-copy strong{font-size:1.15em;color:var(--ink)}\n.brand-copy span{font-size:.88em;color:var(--mut);line-height:1.5}\n.brand-close{display:flex;margin:0 22px 20px auto;min-width:90px;justify-content:center}\n@media(max-width:520px){.brand-card{padding:20px 16px;gap:12px}.brand-card img{width:70px;height:70px;flex-basis:70px}}\n\n.login-card{display:flex;flex-direction:column;gap:1em;text-align:center;padding:2em}\n.login-card p{color:var(--mut);margin:0}\n.login-card small{color:var(--mut)}\n.google-login{justify-content:center;gap:.8em;min-height:50px;font-weight:700}\n.google-login span{display:grid;place-items:center;width:24px;height:24px;border-radius:50%;background:#fff;color:#4285f4;font:bold 16px Arial}\n.nav-logout{min-height:36px;padding:.25em .75em;background:transparent;color:#fff;border-color:#ffffff55}\n.brand-copy small{color:var(--mut);font-size:.82em;margin-top:3px}\n\n/* واجهة لوحة المعلم — تنظيم تنقل ومحتوى */\n.nav .wrap{gap:.45em}\n.nav-brand{display:flex;align-items:center;gap:.65em;margin-inline-end:1em;min-width:max-content;color:#fff}\n.nav-brand>div{display:flex;flex-direction:column;line-height:1.2}\n.nav-brand strong{font-size:1.32rem;letter-spacing:-.04em}\n.nav-brand small{font-size:.7rem;color:#c8e5dc;font-weight:400;margin-top:4px}\n.nav-emblem{width:38px;height:38px;display:grid;place-items:center;border-radius:12px;background:#ffffff20;border:1px solid #ffffff45;font-size:1.25rem;font-weight:800}\n.nav-create{background:#ffffff18;border:1px solid #ffffff3b}\n.nav-account{display:flex;align-items:center;gap:.55em;min-width:0;color:#fff;border-inline-start:1px solid #ffffff30;padding-inline-start:.8em;margin-inline-start:.4em}\n.nav-account small{max-width:180px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:#e0f0eb;font-size:.82rem}\n.nav-avatar{display:grid;place-items:center;width:32px;height:32px;border-radius:50%;background:#e5aa19;color:#23312c;font-weight:800}\n.page-head{display:flex;align-items:center;justify-content:space-between;gap:1.3em;margin:0 0 1.5em;padding:1.25em 1.4em;border-radius:22px;background:linear-gradient(115deg,#e4f4ed,#f9fcfa 62%,#fff);border:1px solid #d9eae2}\n.page-head h1{margin:.15em 0 .35em;color:#123d31}\n.page-head p{margin:0;color:#60746c}\n.eyebrow{font-size:.82rem;font-weight:800;letter-spacing:.04em;color:#078363}\n.page-head-action{white-space:nowrap}\n#main>.row{margin-bottom:1em}\n#main>.row h1{margin-inline-end:auto}\n#main .card h2{margin-bottom:.8em}\n#main .card p{line-height:1.8}\n#main .card .row{row-gap:.55em}\n@media(max-width:850px){.nav-account{display:none}.nav-brand{margin-inline-end:.4em}.nav-brand small{display:none}}\n@media(max-width:620px){.page-head{align-items:flex-start;flex-direction:column;padding:1.05em}.page-head-action{width:100%;justify-content:center}.nav-create{display:none}.nav-brand strong{font-size:1.1rem}.nav .wrap{min-height:60px}}\n\n/* مكتبة المسابقات */\n.library-head{display:flex;justify-content:space-between;align-items:center;gap:1em;margin:0 0 1.1em}\n.library-head h1{margin:.2em 0}.library-head p{margin:0;color:var(--mut)}\n.library-toolbar{display:flex;align-items:center;justify-content:space-between;gap:1em;padding:.75em;background:#fff;border:1px solid var(--line);border-radius:18px}\n.library-tabs{display:flex;gap:.45em;flex-wrap:wrap}\n.library-tabs .btn{border-color:transparent;background:transparent}\n.library-tabs .btn.p{background:var(--g);color:#fff}\n.library-tabs .btn span{display:inline-grid;place-items:center;min-width:22px;height:22px;padding:0 .35em;margin-inline-start:.25em;border-radius:99px;background:#ffffff2c;font-size:.8em}\n.library-search{display:flex;align-items:center;gap:.5em;flex:0 1 410px;min-width:220px;padding-inline:.8em;border:1px solid var(--line);background:#f8fbf9;border-radius:12px}\n.library-search>span{font-size:1.35em;color:var(--mut)}\n.library-search input{border:0;background:transparent;outline:0;box-shadow:none;min-height:42px;padding-inline:.15em}\n.library-summary{display:flex;align-items:center;gap:.5em;margin:1.15em 0 .7em;color:var(--mut);font-size:.9em}\n.library-summary strong{display:grid;place-items:center;min-width:27px;height:27px;border-radius:9px;background:#e6f3ee;color:var(--g);font-size:.9rem}\n.quiz-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,390px),1fr));gap:.9em}\n.quiz-card{padding:1.1em 1.15em;display:flex;flex-direction:column;gap:.9em;transition:transform .16s,border-color .16s,box-shadow .16s}\n.quiz-card:hover{transform:translateY(-2px);border-color:#b4d7c9;box-shadow:0 14px 36px #103d2a13}\n.quiz-card-top{display:flex;align-items:center;gap:.75em;min-width:0}\n.quiz-card-icon{width:44px;height:44px;flex:0 0 44px;border-radius:14px;display:grid;place-items:center;background:#e8f5ef;color:var(--g);font-size:1.35em}\n.quiz-card-title{flex:1;min-width:0}\n.quiz-card-title h3{margin:0 0 .25em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-size:1.05rem}\n.quiz-status{display:inline-flex;align-items:center;gap:.35em;color:#087a58;background:#e7f5ee;border-radius:99px;padding:.1em .55em;font-size:.74em;font-weight:750}\n.quiz-status:before{content:\"\";width:6px;height:6px;border-radius:50%;background:#0b9b68}\n.quiz-status[data-archived]{color:#64717a;background:#eef1f3}\n.quiz-status[data-archived]:before{background:#8b969c}\n.quiz-code{display:flex;flex-direction:column;align-items:flex-end;min-width:76px}\n.quiz-code small{font-size:.7em;color:var(--mut)}\n.quiz-code strong{font-size:1.1em;letter-spacing:.12em;color:var(--g);font-variant-numeric:tabular-nums}\n.quiz-facts{display:flex;align-items:center;gap:.7em;padding:.55em .75em;border-radius:11px;background:#f5f9f7;color:var(--mut);font-size:.85em}\n.quiz-facts b{color:var(--ink);font-size:1.08em}\n.quiz-facts i{height:16px;width:1px;background:var(--line)}\n.quiz-actions{display:flex;align-items:center;gap:.4em;flex-wrap:wrap}\n.quiz-actions .btn{min-height:36px;padding:.3em .7em;font-size:.82em}\n.quiz-actions .btn.p{margin-inline-end:auto}\n.library-empty{grid-column:1/-1;text-align:center;padding:2.8em 1em;border:1px dashed #bfd2ca;border-radius:18px;background:#fbfdfc}\n.library-empty>div{font-size:2rem;color:var(--g)}\n.library-empty p{color:var(--mut);margin:.2em 0 1em}\n@media(max-width:700px){\n .library-head{align-items:flex-start;flex-direction:column}\n .library-head>.btn{width:100%;justify-content:center}\n .library-toolbar{align-items:stretch;flex-direction:column}\n .library-search{min-width:0;flex-basis:auto}\n .quiz-actions .btn.p{margin-inline-end:0}\n .quiz-card{padding:1em}\n}\n\n/* Midmar visual system v2 — consistent colors and accessible contrast */\n:root{\n color-scheme:light;\n --ink:#19294b;--mut:#657492;--bg:#f3f6fd;--card:#ffffff;--line:#dfe6f3;\n --g:#2c61d5;--g2:#2048a4;--gold:#eeb43d;--red:#c94d62;--ok:#159d84;\n --soft:#edf2ff;--soft-2:#e4ebff;--shadow:0 12px 34px rgba(27,54,111,.08);\n}\nhtml[data-theme=\"dark\"]{\n color-scheme:dark;\n --ink:#edf2ff;--mut:#aab8d7;--bg:#0c1530;--card:#151f3e;--line:#2c3b63;\n --g:#82a1ff;--g2:#4268cb;--gold:#ffd078;--red:#ff8799;--ok:#60d7bd;\n --soft:#1a294d;--soft-2:#22345d;--shadow:0 14px 38px rgba(0,0,0,.22);\n}\nhtml{color-scheme:light}\nhtml[data-theme=\"dark\"]{color-scheme:dark}\nbody{background:radial-gradient(ellipse at 90% 0%,color-mix(in srgb,var(--g) 10%,transparent),transparent 38%),var(--bg);color:var(--ink)}\nh1,h2,h3,h4,p,small,strong,b,label,th,td{color:inherit}\nh1{font-weight:750;letter-spacing:-.025em}\nh2,h3{font-weight:700}\np{color:var(--mut)}\nsmall{color:var(--mut)}\na{color:var(--g)}\n.btn{color:var(--ink);background:var(--card);border-color:var(--line);font-weight:600}\n.btn.p{background:var(--g);border-color:var(--g);color:#fff}\n.btn.p:hover{background:var(--g2);border-color:var(--g2)}\n.btn.d{color:var(--red)}\ninput,select,textarea{background:var(--card);border-color:var(--line);color:var(--ink)}\ninput::placeholder,textarea::placeholder{color:var(--mut);opacity:.8}\ninput:focus,select:focus,textarea:focus{border-color:var(--g);outline:3px solid color-mix(in srgb,var(--g) 16%,transparent)}\n.card,.q{background:var(--card);border-color:var(--line);box-shadow:var(--shadow)}\n.nav{background:linear-gradient(110deg,#172f72,#285fd5);box-shadow:0 8px 28px rgba(19,45,113,.22)}\nhtml[data-theme=\"dark\"] .nav{background:linear-gradient(110deg,#101d43,#1e3c82)}\n.nav a{color:#fff}\n.nav a.on,.nav a:hover{background:#ffffff20}\n.nav-logout{color:#fff;background:#ffffff10;border-color:#ffffff55}\n.nav-logout:hover{background:#ffffff1e}\n.nav-brand small{color:#dbe5ff}\n.nav-avatar{background:#f3bd4b;color:#27355f}\n.page-head{background:linear-gradient(115deg,color-mix(in srgb,var(--g) 12%,var(--card)),var(--card) 76%);border-color:var(--line)}\n.page-head h1{color:var(--ink)}\n.page-head p{color:var(--mut)}\n.eyebrow{color:var(--g);font-weight:750}\n.tag{background:var(--soft-2);color:var(--g);font-weight:650}\n.stat b{color:var(--g)}\n.library-toolbar{background:var(--card);border-color:var(--line);box-shadow:var(--shadow)}\n.library-tabs .btn{color:var(--mut)}\n.library-tabs .btn.p{background:var(--g);color:#fff}\n.library-search{background:var(--bg);border-color:var(--line)}\n.library-search input{background:transparent;color:var(--ink)}\n.library-summary{color:var(--mut)}\n.library-summary strong{background:var(--soft-2);color:var(--g)}\n.quiz-card{background:var(--card);border-color:var(--line)}\n.quiz-card:hover{border-color:color-mix(in srgb,var(--g) 55%,var(--line));box-shadow:var(--shadow)}\n.quiz-card-icon{background:var(--soft-2);color:var(--g)}\n.quiz-code strong{color:var(--g)}\n.quiz-facts{background:var(--soft);color:var(--mut)}\n.quiz-facts b{color:var(--ink)}\n.quiz-facts i{background:var(--line)}\n.quiz-status{color:#087a58;background:#e7f5ee}\nhtml[data-theme=\"dark\"] .quiz-status{color:#85e0c8;background:#173d3b}\n.quiz-status[data-archived]{color:#64717a;background:#eef1f3}\nhtml[data-theme=\"dark\"] .quiz-status[data-archived]{color:#bac5dc;background:#2b3652}\n.library-empty{background:var(--card);border-color:var(--line)}\n.library-empty p{color:var(--mut)}\n.q{background:var(--card)}\n.opt input[type=radio]{accent-color:var(--g)}\n.err{color:var(--red)}\n.toast{background:var(--ink);color:var(--bg);box-shadow:var(--shadow)}\ndialog,.brand-dialog{background:var(--card);color:var(--ink);border-color:var(--line)}\n.brand-card img{background:var(--soft)}\n.login-card p,.login-card small{color:var(--mut)}\n.settings-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,310px),1fr));gap:1em;margin-top:1em}\n.settings-card{display:grid;grid-template-columns:48px minmax(0,1fr);gap:.85em;align-items:start}\n.settings-card h2{margin:.05em 0 .45em}\n.settings-card p{margin:.35em 0;line-height:1.8}\n.settings-icon{width:46px;height:46px;border-radius:15px;display:grid;place-items:center;background:var(--soft-2);color:var(--g);font-size:1.35rem;font-weight:800}\n.settings-hint{display:block;color:var(--mut);font-size:.84rem}\n.theme-choices{grid-column:1/-1;display:flex;gap:.6em;flex-wrap:wrap}\n.theme-choices .btn{min-width:145px;justify-content:center}\n.theme-choices .btn.p{color:#fff}\n.theme-toggle{display:inline-flex;align-items:center;justify-content:center;gap:.45em;min-height:36px;padding:.25em .75em;background:#ffffff14;color:#fff;border-color:#ffffff48;font-size:.88rem;white-space:nowrap}\n.theme-toggle:hover{background:#ffffff25;border-color:#ffffff85}\n.theme-toggle span:first-child{font-size:1.15em;line-height:1}\n.nav .theme-toggle{margin-inline-end:.2em}\n.section-heading{margin-bottom:1em}\n.section-heading h1{margin:.2em 0}\n.section-heading p{margin:.2em 0;color:var(--mut)}\n/* Player page follows the selected theme */\nbody.player-page{background:radial-gradient(ellipse at 90% 0%,color-mix(in srgb,var(--g) 11%,transparent),transparent 38%),var(--bg);color:var(--ink)}\n.player-page .top{background:linear-gradient(110deg,#172f72,#285fd5);color:#fff}\nhtml[data-theme=\"dark\"] .player-page .top{background:linear-gradient(110deg,#101d43,#1e3c82)}\n.player-page .wrap>h2{background:var(--card);border-color:var(--line);color:var(--ink);box-shadow:var(--shadow)}\n.player-page .choice{background:var(--card);border-color:var(--line);color:var(--ink);box-shadow:var(--shadow)}\n.player-page .choice:hover{border-color:var(--g)}\n.player-page .choice.sel{border-color:var(--g);background:var(--soft-2)}\n.player-page .choice.right{border-color:var(--ok);background:color-mix(in srgb,var(--ok) 14%,var(--card))}\n.player-page .choice.wrong{border-color:var(--red);background:color-mix(in srgb,var(--red) 12%,var(--card))}\n.player-page .card.narrow h1{color:var(--g)}\n.player-page .tag{background:var(--soft-2);color:var(--g)}\n.player-page .fb.ok{background:color-mix(in srgb,var(--ok) 16%,var(--card));color:var(--ok)}\n.player-page .fb.no{background:color-mix(in srgb,var(--red) 14%,var(--card));color:var(--red)}\n.player-page #ok{background:var(--g);color:#fff}\n.floating-theme-toggle{position:fixed;left:16px;bottom:16px;z-index:30;min-height:42px;padding:.45em .85em;border-radius:13px;background:var(--card);color:var(--ink);border:1px solid var(--line);box-shadow:var(--shadow);font:600 14px 'IBM Plex Sans Arabic',Tahoma,sans-serif;cursor:pointer}\n.floating-theme-toggle:hover{border-color:var(--g)}\n/* Competition board theme palette */\nbody.board-page{background:#0c1734;color:#edf2ff}\n.board-page .hd{background:linear-gradient(110deg,#111f4a,#234eaa);border-color:#ffffff20}\n.board-page .stats{color:#d2defb}\n.board-page .stats span{background:#ffffff0d;border-color:#ffffff20}\n.board-page .qr-card,.board-page .results-card{background:linear-gradient(145deg,#17264a,#121f3c);border-color:#ffffff20}\n.board-page .qr-card h2,.board-page .results-card h2{color:#edf2ff}\n.board-page .qr-card p,.board-page .waiting p{color:#b9c9ed}\n.board-page .waiting h2{color:#ffd078}\n.board-page .progress-wrap{background:#ffffff09;border-color:#ffffff20}\n.board-page .progress-table th,.board-page .progress-table td{border-color:#ffffff20;color:#dbe5ff}\n.board-page .progress-table td,.board-page .rank,.board-page .first small{color:#ffd078}\n.board-page .rank-row{background:#ffffff0a;border-color:#ffffff18;color:#edf2ff}\n.board-page .rank-row.top{background:#dba93518;border-color:#e7bc3c80}\n.board-page .meta,.board-page .active{color:#b9c9ed}\n.board-page .active-list span{background:#ffffff14}\n.board-page .first{background:linear-gradient(135deg,#dba93520,#ffffff08);border-color:#e7bc3c80}\n.board-page .first .time{color:#c7d5f2}\n.board-page .theme-toggle{background:#ffffff12;color:#fff;border-color:#ffffff4c}\nhtml[data-theme=\"light\"] body.board-page{background:radial-gradient(ellipse at 90% 0%,#e0eaff,#f3f6fd 55%,#edf2ff);color:#19294b}\nhtml[data-theme=\"light\"] .board-page .hd{background:linear-gradient(110deg,#e6edff,#ffffff);border-color:#dce5f6;box-shadow:0 8px 26px rgba(32,66,135,.1)}\nhtml[data-theme=\"light\"] .board-page .hd h1{color:#1c3778}\nhtml[data-theme=\"light\"] .board-page .hd .btn{background:#fff;color:#1e459f;border-color:#d9e3f5}\nhtml[data-theme=\"light\"] .board-page .stats{color:#50658c}\nhtml[data-theme=\"light\"] .board-page .stats span{background:#fff;border-color:#dfe7f5}\nhtml[data-theme=\"light\"] .board-page .qr-card,html[data-theme=\"light\"] .board-page .results-card{background:#fff;border-color:#dfe6f3;box-shadow:var(--shadow)}\nhtml[data-theme=\"light\"] .board-page .qr-card h2,html[data-theme=\"light\"] .board-page .results-card h2{color:#20345f}\nhtml[data-theme=\"light\"] .board-page .qr-card p,html[data-theme=\"light\"] .board-page .waiting p{color:#617391}\nhtml[data-theme=\"light\"] .board-page .waiting h2{color:#b27a08}\nhtml[data-theme=\"light\"] .board-page .progress-wrap{background:#f6f8ff;border-color:#dfe6f3}\nhtml[data-theme=\"light\"] .board-page .progress-table th,html[data-theme=\"light\"] .board-page .progress-table td{border-color:#dfe6f3;color:#50658c}\nhtml[data-theme=\"light\"] .board-page .progress-table td,html[data-theme=\"light\"] .board-page .rank,html[data-theme=\"light\"] .board-page .first small{color:#a8750a}\nhtml[data-theme=\"light\"] .board-page .rank-row{background:#f7f9ff;border-color:#e2e8f5;color:#20345f}\nhtml[data-theme=\"light\"] .board-page .rank-row.top{background:#fff7df;border-color:#e4bd62}\nhtml[data-theme=\"light\"] .board-page .meta,html[data-theme=\"light\"] .board-page .active{color:#687997}\nhtml[data-theme=\"light\"] .board-page .active-list span{background:#edf2ff}\nhtml[data-theme=\"light\"] .board-page .first{background:linear-gradient(135deg,#fff7df,#fff);border-color:#e4bd62}\nhtml[data-theme=\"light\"] .board-page .first .time{color:#687997}\nhtml[data-theme=\"light\"] .board-page .theme-toggle{background:#fff;color:#1e459f;border-color:#d9e3f5}\n@media(max-width:650px){.settings-card{grid-template-columns:40px minmax(0,1fr)}.theme-choices{flex-direction:column}.theme-choices .btn{width:100%}}\n","/board.html":"<!doctype html>\n<html lang=\"ar\" dir=\"rtl\">\n<head>\n<meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>لوحة المسابقة – مِضمار</title><link rel=\"stylesheet\" href=\"/style.css\">\n<style>\n:root{color-scheme:dark}\nbody{background:#09271f;color:#fff;min-height:100vh;overflow-x:hidden}\n.hd{display:flex;align-items:center;gap:1em;padding:1em 2vw;border-bottom:1px solid #ffffff20}\n.hd h1{margin:0;font-size:clamp(1.4rem,3vw,2.6rem)}\n.hd .spacer{flex:1}\n.hd .btn{background:#ffffff12;color:#fff;border-color:#ffffff35}\n.stats{display:flex;gap:1.5em;padding:.8em 2vw;color:#bfe3d5;font-size:clamp(.95rem,1.5vw,1.3rem);flex-wrap:wrap}\n.stage{padding:2vh 2vw 4vh;display:grid;grid-template-columns:minmax(0,1fr);gap:2vw;align-items:start}.stage.has-completed{grid-template-columns:minmax(190px,260px) minmax(0,1fr)}\n.qr-card,.results-card{background:#ffffff0c;border:1px solid #ffffff20;border-radius:20px;padding:1.2em}\n.qr-card{text-align:center;position:sticky;top:1em}\n.qr-card img{display:block;width:min(100%,340px);aspect-ratio:1;object-fit:contain;background:#fff;border-radius:12px;padding:10px;margin:.8em auto}\n.qr-card.compact img{width:min(100%,150px)}.qr-card.compact{padding:.8em}.qr-card .code{font-size:1.5em;font-weight:700;letter-spacing:.12em;color:#f2b705}\n.qr-card p{margin:.25em 0;color:#c6ddd5}\n.results-card{min-height:300px}\n.waiting{text-align:center;padding:6vh 1em}\n.waiting h2{font-size:clamp(1.5rem,3vw,2.8rem);color:#f2b705}\n.waiting p{color:#c6ddd5;font-size:1.1rem}\n.first{border:1px solid #f2b70570;background:linear-gradient(135deg,#f2b70524,#ffffff08);border-radius:16px;padding:1em;margin-bottom:1em}\n.first small{color:#f2b705;font-weight:700}\n.first strong{display:block;font-size:clamp(1.5rem,3vw,2.4rem);margin:.25em 0}\n.first .time{color:#c6ddd5}\n.rank-list{display:grid;gap:.6em}\n.progress-wrap{background:#ffffff0c;border:1px solid #ffffff20;border-radius:16px;padding:1em;margin-bottom:1em}.progress-table{border-collapse:collapse;width:100%;min-width:420px;text-align:center}.progress-table th,.progress-table td{padding:.65em;border-bottom:1px solid #ffffff20}.progress-table th:first-child{text-align:right;min-width:130px}.progress-table td{color:#f2b705;font-weight:800}.progress-table td:has(+td){ }\n.rank-row{display:flex;align-items:center;gap:.8em;background:#ffffff0c;border:1px solid #ffffff12;border-radius:12px;padding:.75em 1em;font-size:clamp(.95rem,1.5vw,1.25rem)}\n.rank-row.top{border-color:#f2b70580;background:#f2b70517}\n.rank{width:2em;font-weight:800;color:#f2b705}\n.team{flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.score{font-weight:700;white-space:nowrap}\n.meta{color:#b7ccc4;font-size:.88em;white-space:nowrap}\n.active{margin-top:1.2em;color:#b7ccc4}\n.active summary{cursor:pointer;padding:.5em}\n.active-list{display:flex;flex-wrap:wrap;gap:.5em;padding:.5em}\n.active-list span{background:#ffffff12;border-radius:99px;padding:.2em .8em}\n.brand-mark{margin-inline-start:0;width:46px;height:46px;flex-basis:46px}\ncanvas{position:fixed;inset:0;pointer-events:none;z-index:9}\n@media(max-width:760px){.stage,.stage.has-completed{grid-template-columns:1fr}.qr-card{position:static;order:0}.results-card{order:1}.qr-card img{width:190px}}\n</style>\n<style>\n.hd{position:sticky;top:0;z-index:5;background:linear-gradient(110deg,#06251e,#0b4735);box-shadow:0 8px 26px #0003;padding:1em 2.2vw}\n.hd h1{font-weight:800;letter-spacing:-.035em}\n.stats{gap:.65em;padding:1em 2vw}\n.stats span{background:#ffffff0b;border:1px solid #ffffff18;border-radius:99px;padding:.35em .85em}\n.stage{max-width:1680px;margin:0 auto;padding:1.2em 2vw 3em}\n.qr-card,.results-card{background:linear-gradient(145deg,#ffffff12,#ffffff08);border-color:#ffffff24;box-shadow:0 14px 35px #0002;border-radius:22px}\n.qr-card h2{font-size:1.2em}\n.qr-card img{box-shadow:0 8px 26px #0003}\n.results-card{min-height:360px}\n.progress-wrap{background:#ffffff0a;border-color:#ffffff22;border-radius:18px}\n.progress-table th,.progress-table td{padding:.72em}\n.rank-row{border-radius:15px;padding:.9em 1.1em;background:#ffffff0d}\n.rank-row.top{border-color:#e7bc3c;background:linear-gradient(110deg,#e4b32c25,#ffffff09)}\n.first{border-radius:19px;border-color:#e7bc3c88}\n.waiting{padding:7vh 1.2em}\n.brand-mark{border:1px solid #ffffff4a;border-radius:13px;background:#ffffff12;overflow:hidden}\n.brand-mark img{width:30px;height:30px}\n@media(max-width:760px){.hd{padding:.8em 1em}.stats{padding:.7em 1em}.stage{padding:1em}.results-card,.qr-card{border-radius:17px}}\n</style></head>\n<body class=\"board-page\">\n<header class=\"hd\"><h1 id=\"title\">مِضمار – لوحة المسابقة</h1><span class=\"spacer\"></span><button class=\"btn\" id=\"fs\">ملء الشاشة</button><button class=\"btn theme-toggle\" id=\"themeToggle\" type=\"button\">☾ الوضع المظلم</button><span class=\"brand-mark\" title=\"حقوق إنتريت\" aria-label=\"حقوق إنتريت\"><img src=\"/entrit-logo.svg\" alt=\"إنتريت\"></span></header>\n<div class=\"stats\"><span id=\"joined\">الفرق المشاركة: 0</span><span id=\"finished\">أنهت المسابقة: 0</span><span id=\"playing\">تلعب الآن: 0</span></div>\n<main class=\"stage\">\n<aside class=\"qr-card\" id=\"qr-card\"><h2>امسح رمز QR للانضمام</h2><img id=\"qr\" alt=\"رمز الانضمام\"><div class=\"code\" id=\"code\"></div><p>افتح كاميرا الجوال وامسح الرمز</p><p id=\"join-url\" style=\"font-size:.8em;overflow-wrap:anywhere\"></p></aside>\n<section class=\"results-card\" id=\"results\"><div class=\"waiting\"><h2>بانتظار الفرق</h2><p>امسحوا رمز QR للانضمام إلى المسابقة</p></div></section>\n</main><canvas id=\"confetti\"></canvas>\n\n<script>\nconst code=location.pathname.split('/').pop(),$=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst duration=s=>{s=Math.max(0,Number(s)||0);return s>=60?Math.floor(s/60)+'د '+String(s%60).padStart(2,'0')+'ث':s+'ث'};\nconst joinUrl=location.origin+'/j/'+encodeURIComponent(code);\n$('qr').src='/api/qr?text='+encodeURIComponent(joinUrl);$('code').textContent=code;$('join-url').textContent=joinUrl;\n$('fs').onclick=()=>document.fullscreenElement?document.exitFullscreen():document.documentElement.requestFullscreen();\nconst THEME_KEY='midmar-theme';\nfunction setBoardTheme(theme,save=true){const next=theme==='dark'?'dark':'light';document.documentElement.dataset.theme=next;if(save)localStorage.setItem(THEME_KEY,next);const b=$('themeToggle');if(b){b.innerHTML=next==='dark'?'☀ الوضع الساطع':'☾ الوضع المظلم';b.setAttribute('aria-label',next==='dark'?'التبديل إلى الوضع الساطع':'التبديل إلى الوضع المظلم')}}\nsetBoardTheme(localStorage.getItem(THEME_KEY)||(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'),false);\n$('themeToggle').onclick=()=>setBoardTheme(document.documentElement.dataset.theme==='dark'?'light':'dark');\nlet boardRefreshTimer=null;\nasync function refreshBoard(){try{const r=await fetch('/api/board/'+encodeURIComponent(code),{cache:'no-store'});if(!r.ok)return;const d=await r.json();const signature=JSON.stringify(d);if(signature!==window.lastBoardSignature){window.lastBoardSignature=signature;draw(d)}}catch(e){console.warn('تعذر تحديث اللوحة',e)}}\nrefreshBoard();boardRefreshTimer=setInterval(refreshBoard,1200);\nlet announced=null;\nfunction progressMatrix(d){if(!d.rows?.length)return '<div class=\"waiting\"><p>لا يوجد مشاركون حتى الآن.</p></div>';const qs=d.questions||[];return `<div class=\"progress-wrap\"><h2>متابعة تقدم المشاركين</h2><div style=\"overflow:auto\"><table class=\"progress-table\"><thead><tr><th>المشارك</th>${qs.map((q,i)=>`<th>س${i+1}</th>`).join('')}</tr></thead><tbody>${d.rows.map(r=>`<tr><th>${esc(r.name)}</th>${(r.progress||[]).map(p=>`<td title=\"${p.status==='done'?'مكتمل':p.status==='active'?'قيد التنفيذ':'لم يبدأ'}\">${p.status==='done'?'✓':p.status==='active'?'◉':'·'}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class=\"meta\">✓ مكتمل · ◉ قيد التنفيذ · · لم يبدأ</p></div>`}\nfunction draw(d){\n $('title').textContent='مِضمار – '+d.title;\n $('joined').textContent='الفرق المشاركة: '+(d.rows?.length||0);\n $('finished').textContent='أنهت المسابقة: '+d.finished;\n $('playing').textContent='تلعب الآن: '+d.playing;\n const completed=(d.rows||[]).filter(r=>r.done).sort((a,b)=>b.score-a.score||a.duration-b.duration||a.id-b.id);\n const active=(d.rows||[]).filter(r=>!r.done);\n const qr=$('qr-card'),stage=document.querySelector('.stage');\n if(!completed.length){\n  stage.classList.remove('has-completed');qr.classList.remove('compact');\n  $('results').innerHTML=progressMatrix(d)+'<div class=\"waiting\"><h2>بانتظار اكتمال المشاركين</h2><p>تظهر حالة الإجابة لكل مشارك مباشرة عند إرسالها.</p><p>المشاركون: <b>'+((d.rows||[]).length)+'</b></p></div>';\n  return;\n }\n stage.classList.add('has-completed');qr.classList.add('compact');\n if(d.hidden){$('results').innerHTML=progressMatrix(d)+'<div class=\"waiting\"><h2>الترتيب مخفي مؤقتًا</h2><p>متابعة تقدم المشاركين ما زالت ظاهرة.</p></div>';return;}\n const first=[...completed].sort((a,b)=>(a.finishedAt||Number.MAX_SAFE_INTEGER)-(b.finishedAt||Number.MAX_SAFE_INTEGER))[0]||completed[0];\n const rows=completed.map((r,i)=>'<div class=\"rank-row '+(i===0?'top':'')+'\"><span class=\"rank\">'+(i===0?'🥇':i===1?'🥈':i===2?'🥉':(i+1))+'</span><span class=\"team\">'+esc(r.name)+'</span><span class=\"score\">'+r.score+'/'+d.totalPoints+'</span><span class=\"meta\">'+duration(r.duration)+'</span></div>').join('');\n const activeHtml=active.length?'<details class=\"active\"><summary>فرق لم تنه الإجابة بعد ('+active.length+')</summary><div class=\"active-list\">'+active.map(r=>'<span>'+esc(r.name)+'</span>').join('')+'</div></details>':'';\n $('results').innerHTML=progressMatrix(d)+'<div class=\"first\"><small>اكتمل المشارك الأول</small><strong>'+esc(first.name)+'</strong><span class=\"time\">الدرجة '+first.score+'/'+d.totalPoints+' · الزمن '+duration(first.duration)+'</span></div><h2>ترتيب الفرق المكتملة</h2><div class=\"rank-list\">'+rows+'</div>'+activeHtml;\n const signature=first.id+':'+first.score+':'+first.duration;\n if(active.length===0&&announced!==signature){announced=signature;confetti()}\n}\nfunction confetti(){\n if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;\n const c=$('confetti'),ctx=c.getContext('2d');c.width=innerWidth;c.height=innerHeight;\n const colors=['#f2b705','#fff','#1fbf8f','#e8643c'];\n const parts=Array.from({length:140},()=>({x:Math.random()*c.width,y:-20-Math.random()*c.height*.4,v:2+Math.random()*4,r:4+Math.random()*6,color:colors[Math.random()*colors.length]}));\n let frame=0;(function animate(){ctx.clearRect(0,0,c.width,c.height);for(const p of parts){p.y+=p.v;ctx.fillStyle=p.color;ctx.fillRect(p.x,p.y,p.r,p.r*1.6)}if(++frame<180)requestAnimationFrame(animate);else ctx.clearRect(0,0,c.width,c.height)})();\n}\n</script></body></html>","/play.html":"<!doctype html><html lang=\"ar\" dir=\"rtl\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>مِضمار</title><link rel=\"stylesheet\" href=\"/style.css\">\n<style>body{-webkit-user-select:none;user-select:none}.top{background:var(--g2);color:#fff;padding:.6em 1em}.top .bar{background:rgba(255,255,255,.25)}.top .bar i{background:var(--gold)}\n.choice{display:block;width:100%;text-align:right;font-size:1.15em;padding:.9em 1em;margin:.5em 0;border:2px solid var(--line);border-radius:14px;background:var(--card);cursor:pointer;min-height:56px}\n.choice.sel{border-color:var(--g);background:rgba(14,124,90,.12)}.choice.right{border-color:var(--ok);background:rgba(30,142,90,.2)}.choice.wrong{border-color:var(--red);background:rgba(194,58,58,.15)}\n.big{font-size:3em;font-weight:700;line-height:1.1}.fb{padding:.6em 1em;border-radius:10px;margin:.6em 0;font-weight:700}.fb.ok{background:rgba(30,142,90,.2)}.fb.no{background:rgba(194,58,58,.15)}</style>\n<style>\nbody{background:linear-gradient(145deg,#edf5f1,#f7f9f8 55%,#eef4f1);color:#1b3037}\n#app{min-height:100vh}\n.top{position:sticky;top:0;z-index:6;background:linear-gradient(115deg,#075b49,#0b8667);box-shadow:0 8px 28px #073c2d28;padding:.8em max(1em,calc((100vw - 760px)/2))}\n.top .row{gap:.8em}\n.top b{font-size:1.08em;letter-spacing:-.02em}\n.top .bar{height:7px;border-radius:99px;background:#ffffff35}\n.top .bar i{border-radius:99px;background:#f2c44c}\n.wrap{max-width:760px;padding:1.5em 1.1em 3em}\n.wrap>h2{margin:.3em 0 1em;padding:1.15em 1.25em;background:#fff;border:1px solid #dce8e3;border-radius:18px;box-shadow:0 8px 26px #153d2d0c;font-size:clamp(1.2rem,3vw,1.7rem);line-height:1.65}\n.choice{border-radius:15px;border:1.5px solid #d9e5df;background:#fff;min-height:58px;padding:1em 1.1em;margin:.7em 0;font-weight:650;box-shadow:0 3px 12px #183d2b08;transition:transform .15s,border-color .15s,background .15s}\n.choice:hover{border-color:#8db9a7;transform:translateY(-1px)}\n.choice.sel{border-color:#0e8765;background:#e8f5ef;box-shadow:0 0 0 3px #0e87651a}\n.choice.right{border-color:#16855d;background:#e5f6ee}\n.choice.wrong{border-color:#bd4952;background:#fff0f1}\n#ok{min-height:52px;border-radius:15px;margin-top:1em;font-weight:750;box-shadow:0 8px 22px #087f6322}\n#ok:disabled{opacity:.55;box-shadow:none}\n.fb{border-radius:13px;padding:.8em 1em}\n.card.narrow{border-radius:22px;border-color:#d9e6e0;box-shadow:0 18px 50px #153e3016}\n.card.narrow h1{color:#0a7157}\n.tag{margin:.35em 0}\n@media(max-width:560px){.top{padding:.7em .85em}.wrap{padding:1em .8em 2em}.wrap>h2{padding:.95em}.choice{font-size:1.02em}}\n</style></head><body class=\"player-page\"><div id=app></div>\n<script>\nconst code=location.pathname.split('/').pop(),KEY='mid_'+code,app=document.getElementById('app');let token=localStorage.getItem(KEY),S=null,sel=null,orderSel=[],busy=false,timer=null,waitTimer=null,off=0;\nconst esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst THEME_KEY='midmar-theme';\nfunction setPlayerTheme(theme,save=true){const next=theme==='dark'?'dark':'light';document.documentElement.dataset.theme=next;if(save)localStorage.setItem(THEME_KEY,next);const b=document.getElementById('playerThemeToggle');if(b){b.textContent=next==='dark'?'☀ الوضع الساطع':'☾ الوضع المظلم';b.setAttribute('aria-label',next==='dark'?'التبديل إلى الوضع الساطع':'التبديل إلى الوضع المظلم')}}\nsetPlayerTheme(localStorage.getItem(THEME_KEY)||(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'),false);\nconst playerThemeButton=document.createElement('button');playerThemeButton.id='playerThemeToggle';playerThemeButton.className='floating-theme-toggle';playerThemeButton.type='button';playerThemeButton.onclick=()=>setPlayerTheme(document.documentElement.dataset.theme==='dark'?'light':'dark');document.body.append(playerThemeButton);\n\nasync function api(u,m='GET',b){const r=await fetch(u,{method:m,headers:b?{'Content-Type':'application/json'}:{},body:b?JSON.stringify(b):undefined});const j=await r.json().catch(()=>({}));if(!r.ok){const e=Error(j.error||'حدث خطأ');e.data=j;throw e}return j}\nasync function start(){if(token){try{S=await api('/api/play/'+token);off=S.now-Date.now();return game()}catch(e){localStorage.removeItem(KEY);token=null}}\n try{const i=await api('/api/join/'+code);intro(i)}catch(e){app.innerHTML=`<div class=center><div class=\"card narrow\"><h2>تعذّر فتح المسابقة</h2><p>${esc(e.message)}</p></div></div>`}}\nfunction intro(i){const student=i.participation_mode==='students',roster=i.roster||[];app.innerHTML=`<div class=center><div class=\"card narrow\"><h1>${esc(i.title)}</h1>${i.image?`<img src=\"${i.image}\" alt=\"\" style=\"max-width:100%;border-radius:10px\">`:''}<p>${esc(i.description)}</p>\n <p class=tag>${i.nq} سؤال${i.time_limit?` · ${i.time_limit} دقيقة`:''}</p><p>${student?'مشاركة فردية – كل طالب يشارك من جهازه.':'مشاركة جماعية – جوال واحد لكل مجموعة.'}</p>\n ${i.status==='open'?`${student&&i.entry_mode!=='qr'&&roster.length?`<label for=roster>اختر اسمك من قائمة المعلم</label><select id=roster><option value=\"\">اختيار الاسم</option>${roster.map(x=>`<option value=\"${x.id}\">${esc(x.name)}</option>`).join('')}</select>`:''}${!student||i.entry_mode!=='roster'?`<label for=n>${student?'اسم الطالب':'اسم المجموعة'}</label><input id=n maxlength=40 autocomplete=off>`:''}<p class=err id=e></p><button class=\"btn p\" id=go style=\"width:100%;justify-content:center\">${student?'ابدأ المشاركة':'ابدئي المسابقة'}</button>`:`<p class=err>المسابقة ${esc(i.status)}</p>`}</div></div>`;\n const go=document.getElementById('go');if(go)go.onclick=async()=>{go.disabled=true;try{const payload={name:document.getElementById('n')?.value,roster_id:document.getElementById('roster')?.value};const r=await api('/api/join/'+code,'POST',payload);token=r.token;localStorage.setItem(KEY,token);S=await api('/api/play/'+token);off=S.now-Date.now();game()}catch(e){document.getElementById('e').textContent=e.message;go.disabled=false}}}\nfunction game(){clearInterval(timer);clearInterval(waitTimer);if(S.done)return end();if(S.waiting){app.innerHTML=`<div class=center><div class=\"card narrow\" style=\"text-align:center\"><h2>بانتظار المعلم</h2><p>أكملت السؤال المتاح. سيظهر السؤال التالي هنا عند فتحه من لوحة المعلم.</p><div class=tag>لا تغلق الصفحة</div></div></div>`;waitTimer=setInterval(async()=>{try{S=await api('/api/play/'+token);off=S.now-Date.now();if(!S.waiting)game()}catch(e){}},1500);return}sel=null;busy=false;const q=S.question;orderSel=q.type==='order'?q.options.map(x=>x.i).sort(()=>Math.random()-.5):[];\n app.innerHTML=`<div class=top><div class=row><b>${esc(S.title)}</b><span class=sp></span><span id=tm></span></div><div class=row><small>${esc(S.group)}</small><span class=sp></span><small>سؤال ${S.answered+1} من ${S.total}</small></div><div class=bar style=\"margin-top:.4em\"><i style=\"width:${100*S.answered/S.total}%\"></i></div></div>\n <div class=wrap style=\"max-width:640px\"><h2 style=\"margin-top:.8em\">${esc(q.text)}</h2>${q.image?`<img src=\"${q.image}\" alt=\"\" style=\"max-width:100%;border-radius:10px\">`:''}<div id=ch>${q.type==='order'?orderSel.map((n,i)=>`<div class=choice style=\"display:flex;align-items:center;gap:.5em\"><b>${i+1}.</b><span class=sp>${esc(q.options.find(x=>x.i===n).t)}</span><button class=\"btn s\" data-move=\"up\" data-pos=${i} ${i===0?'disabled':''}>↑</button><button class=\"btn s\" data-move=\"down\" data-pos=${i} ${i===orderSel.length-1?'disabled':''}>↓</button></div>`).join(''):` ${q.options.map(o=>`<button class=choice data-i=${o.i}>${esc(o.t)}</button>`).join('')}`}</div><div id=fb></div>\n <button class=\"btn p\" id=ok disabled style=\"width:100%;justify-content:center;font-size:1.1em\">تأكيد الإجابة</button></div>`;\n if(S.progression_mode==='free'){api('/api/play/'+token+'/questions').then(d=>{const nav=document.createElement('div');nav.className='card';nav.style.cssText='display:flex;gap:.4em;flex-wrap:wrap;margin:1em 0';nav.innerHTML='<b style=\"width:100%\">اختر السؤال:</b>'+d.questions.map(q=>`<button class=\"btn ${q.answered?'s':'p'}\" ${q.answered?'disabled':''} data-q=\"${q.id}\">سؤال ${q.index}</button>`).join('');app.querySelector('.wrap').prepend(nav);nav.onclick=async e=>{const btn=e.target.closest('[data-q]');if(!btn)return;try{S=await api('/api/play/'+token+'?question_id='+btn.dataset.q);game()}catch(err){console.warn(err)}}}).catch(()=>{})}\n document.getElementById('ch').onclick=e=>{if(busy)return;const mv=e.target.closest('[data-move]');if(mv){const p=+mv.dataset.pos,to=mv.dataset.move==='up'?p-1:p+1;if(to>=0&&to<orderSel.length){[orderSel[p],orderSel[to]]=[orderSel[to],orderSel[p]];gameOrderDraw(q)}return}const b=e.target.closest('.choice[data-i]');if(!b)return;sel=+b.dataset.i;document.querySelectorAll('.choice').forEach(x=>x.classList.toggle('sel',x===b));document.getElementById('ok').disabled=false};\n document.getElementById('ok').onclick=submit;if(q.type==='order'){document.getElementById('ok').disabled=false;window.gameOrderDraw=gameOrderDraw}tick();if(S.deadline)timer=setInterval(tick,500)}\nfunction gameOrderDraw(q){const box=document.getElementById('ch');if(!box)return;box.innerHTML=orderSel.map((n,i)=>`<div class=choice style=\"display:flex;align-items:center;gap:.5em\"><b>${i+1}.</b><span class=sp>${esc(q.options.find(x=>x.i===n).t)}</span><button class=\"btn s\" data-move=\"up\" data-pos=${i} ${i===0?'disabled':''}>↑</button><button class=\"btn s\" data-move=\"down\" data-pos=${i} ${i===orderSel.length-1?'disabled':''}>↓</button></div>`).join('')}\nfunction tick(){if(!S.deadline)return;const t=Math.max(0,Math.ceil((S.deadline-(Date.now()+off))/1000)),el=document.getElementById('tm');if(el)el.textContent=`${Math.floor(t/60)}:${String(t%60).padStart(2,'0')}`;\n if(t<=0){clearInterval(timer);api('/api/play/'+token).then(s=>{S=s;if(s.done)end()})}}\nasync function submit(){if(sel===null||busy)return;busy=true;const btn=document.getElementById('ok');btn.disabled=true;\n try{const r=await api('/api/play/'+token+'/answer','POST',S.question.type==='order'?{question_id:S.question.id,order:orderSel}:{question_id:S.question.id,choice:sel});S=r.state;\n  if(r.correct===null)return game();if(S.question?.type!=='order')document.querySelectorAll('.choice[data-i]').forEach(x=>{const i=+x.dataset.i;if(i===r.right)x.classList.add('right');else if(i===sel)x.classList.add('wrong')});\n  document.getElementById('fb').innerHTML=`<div class=\"fb ${r.correct?'ok':'no'}\">${r.correct?'إجابة صحيحة!':'إجابة خاطئة'}</div>`;btn.textContent='السؤال التالي';btn.disabled=false;btn.onclick=game}\n catch(e){if(e.data?.state){S=e.data.state;return game()}busy=false;btn.disabled=false;document.getElementById('fb').innerHTML=`<p class=err>${esc(e.message)}</p>`}}\nfunction end(){clearInterval(timer);const m=Math.floor(S.duration/60),s=S.duration%60;app.innerHTML=`<div class=center><div class=\"card narrow\" style=\"text-align:center\"><h1>انتهت المسابقة</h1><p>${esc(S.group)}</p><div class=big>${S.score}<small style=\"font-size:.4em;color:var(--mut)\"> / ${S.totalPoints}</small></div>\n <p>${S.correct} إجابة صحيحة من ${S.total} · الوقت ${m}د ${s}ث</p>${S.rank?`<p class=tag>مركزكم الحالي: ${S.rank}</p>`:''}<p>تابعي لوحة المتصدرات على شاشة الفصل.</p>${S.retry?'<button class=\"btn p\" id=rt>إعادة المحاولة</button>':''}</div></div>`;\n const r=document.getElementById('rt');if(r)r.onclick=async()=>{await api('/api/play/'+token+'/retry','POST');S=await api('/api/play/'+token);off=S.now-Date.now();game()}}\nstart();\n</script></body></html>\n","/entrit-logo.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 256 314\"><image width=\"256\" height=\"314\" href=\"data:image/png;base64,\"/></svg>"};
